__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEVEL_DATA",{enumerable:!0,get:function(){return u}});var t=r(d[0]),n=r(d[1]),_=r(d[2]),o=r(d[3]);const u={words:(0,r(d[4]).withExamples)(o.N5_WORDS,_.N5_EXAMPLES),grammar:t.N5_GRAMMAR,reading:n.N5_READING}},1230,[1231,1232,1233,1234,1235]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N5_GRAMMAR",{enumerable:!0,get:function(){return n}});const n=[{id:'n5-g01',pattern:'〜たい',connection:'動詞ます形 ＋ たい',meaning:'想要做〜',example:{ja:'日本へ行きたいです。',zh:'我想去日本。',highlight:'行きたい'},tip:'「〜たい」用於說話者自己；第三人稱想要做某事要用「〜たがる」。對象助詞可用を或が。',quiz:{blank:'たい',distractors:['たがる','ながら','ましょう']}},{id:'n5-g02',pattern:'〜てください',connection:'動詞て形 ＋ ください',meaning:'請〜',example:{ja:'ここに名前を書いてください。',zh:'請在這裡寫名字。',highlight:'書いてください'},tip:'接在て形後，注意五段動詞音便（書く→書いて、読む→読んで）。比「〜てくれませんか」直接。',quiz:{blank:'てください',distractors:['ています','てから','たいです']}},{id:'n5-g03',pattern:'〜ないでください',connection:'動詞ない形 ＋ でください',meaning:'請不要〜',example:{ja:'ここで写真を撮らないでください。',zh:'請不要在這裡拍照。',highlight:'撮らないでください'},tip:'接ない形＋でください，不可說「〜なくてください」，是考試常見陷阱。',quiz:{blank:'ないでください',distractors:['なくてください','ないください','てください']}},{id:'n5-g04',pattern:'〜ている',connection:'動詞て形 ＋ いる',meaning:'正在〜；（狀態）',example:{ja:'弟は今、テレビを見ています。',zh:'弟弟現在正在看電視。',highlight:'見ています'},tip:'「〜ている」除了進行中，也表示結果狀態（結婚している、知っている）。',quiz:{blank:'ています',distractors:['てあります','てください','たいです']}},{id:'n5-g05',pattern:'〜てもいい',connection:'動詞て形 ＋ もいい',meaning:'可以〜',example:{ja:'窓を開けてもいいですか。',zh:'可以打開窗戶嗎？',highlight:'開けてもいい'},tip:'問句「〜てもいいですか」請求許可；否定回答常用「〜てはいけません」或「すみません、ちょっと…」。',quiz:{blank:'てもいい',distractors:['てはいけない','てください','ながら']}},{id:'n5-g06',pattern:'〜てはいけない',connection:'動詞て形 ＋ はいけない',meaning:'不可以〜',example:{ja:'ここでたばこを吸ってはいけません。',zh:'這裡不可以抽菸。',highlight:'吸ってはいけません'},tip:'與「〜てもいい」為一組考點：て＋は＋いけない表禁止，口語縮約為「〜ちゃいけない」。',quiz:{blank:'てはいけません',distractors:['てもいいです','ています','たいです']}},{id:'n5-g07',pattern:'〜ましょう',connection:'動詞ます形 ＋ ましょう',meaning:'一起〜吧',example:{ja:'いっしょに帰りましょう。',zh:'一起回家吧。',highlight:'帰りましょう'},tip:'「〜ましょう」積極提議一起做；「〜ませんか」較客氣，先詢問對方意願。',quiz:{blank:'ましょう',distractors:['ました','たい','ながら']}},{id:'n5-g08',pattern:'〜から',connection:'普通形／丁寧形 ＋ から',meaning:'因為〜',example:{ja:'雨ですから、出かけません。',zh:'因為下雨，所以不出門。',highlight:'ですから'},tip:'「から」主觀說明理由，後句可接命令、請求；「ので」較客觀、禮貌。',quiz:{blank:'から',distractors:['まで','が','ても']}},{id:'n5-g09',pattern:'AよりBのほうが',connection:'名詞 ＋ より、名詞 ＋ のほうが',meaning:'B 比 A 更〜',example:{ja:'バスより電車のほうが速いです。',zh:'電車比公車快。',highlight:'より電車のほうが'},tip:'「AよりBのほうが〜」：より前是比較基準（較差的一方），注意不要把A、B順序弄反。',quiz:{blank:'より',distractors:['から','まで','にも']}},{id:'n5-g10',pattern:'〜がほしい',connection:'名詞 ＋ がほしい',meaning:'想要（東西）',example:{ja:'新しいかばんがほしいです。',zh:'我想要新包包。',highlight:'がほしい'},tip:'「ほしい」用於想要東西，對象用が；想要做某動作則用「動詞ます形＋たい」。',quiz:{blank:'ほしい',distractors:['たい','ください','いる']}},{id:'n5-g11',pattern:'〜前に',connection:'動詞辭書形／名詞の ＋ 前に',meaning:'在〜之前',example:{ja:'寝る前に歯をみがきます。',zh:'睡覺前刷牙。',highlight:'寝る前に'},tip:'動詞一定用辭書形（行く前に），即使整句是過去式；名詞要加の（食事の前に）。',quiz:{blank:'前に',distractors:['後で','ながら','まで']}},{id:'n5-g12',pattern:'〜たり〜たりする',connection:'動詞た形 ＋ り、動詞た形 ＋ り ＋ する',meaning:'又〜又〜（列舉動作）',example:{ja:'日曜日は本を読んだり、映画を見たりします。',zh:'星期天會看看書、看看電影。',highlight:'読んだり'},tip:'通常成對使用並以「する」結尾，表示舉例部分動作；「〜ながら」才是同時進行。',quiz:{blank:'たりします',distractors:['ています','ましょう','てください']}},{id:'n5-g13',pattern:'〜ませんか',connection:'動詞ます形 ＋ ませんか',meaning:'要不要一起〜？（邀約）',example:{ja:'週末、一緒に映画を見ませんか。',zh:'週末要不要一起看電影？',highlight:'見ませんか'},tip:'「〜ませんか」客氣邀約；回答同意時常說「ええ、〜ましょう」。',quiz:{blank:'ませんか',distractors:['ましたか','ませんでした','たいですか']}},{id:'n5-g14',pattern:'〜ましょうか',connection:'動詞ます形 ＋ ましょうか',meaning:'我來〜吧？；要不要〜？',example:{ja:'荷物が重そうですね。持ちましょうか。',zh:'行李好像很重，我來幫你拿吧？',highlight:'持ちましょうか'},tip:'「〜ましょうか」主動提議幫忙（我來〜吧？）；「〜ませんか」則是邀請對方一起做。',quiz:{blank:'ましょうか',distractors:['ませんか','ましたか','たいですか']}},{id:'n5-g15',pattern:'〜後で',connection:'動詞た形／名詞の ＋ 後で',meaning:'〜之後',example:{ja:'授業の後で、図書館へ行きます。',zh:'下課之後要去圖書館。',highlight:'授業の後で'},tip:'動詞要用た形（食べた後で），名詞加の；與「〜てから」相比，後で較單純表時間先後。',quiz:{blank:'後で',distractors:['前に','ながら','から']}},{id:'n5-g16',pattern:'〜てから',connection:'動詞て形 ＋ から',meaning:'做完〜之後再〜',example:{ja:'手を洗ってから、ご飯を食べます。',zh:'洗完手之後再吃飯。',highlight:'洗ってから'},tip:'「〜てから」強調先做完前項再做後項；動詞一律用て形，不可用た形。',quiz:{blank:'てから',distractors:['たから','てまで','ながら']}},{id:'n5-g17',pattern:'〜ながら',connection:'動詞ます形 ＋ ながら',meaning:'一邊〜一邊〜',example:{ja:'音楽を聞きながら、勉強します。',zh:'一邊聽音樂一邊讀書。',highlight:'聞きながら'},tip:'主要動作放在後句，「ながら」前是附帶動作；兩動作主語必須相同。',quiz:{blank:'ながら',distractors:['たり','てから','まで']}},{id:'n5-g18',pattern:'〜が（逆接）',connection:'普通形／丁寧形 ＋ が',meaning:'雖然〜但是〜',example:{ja:'この店は安いですが、あまりおいしくないです。',zh:'這家店雖然便宜，但不太好吃。',highlight:'安いですが'},tip:'逆接的「が」接在句末普通形或丁寧形後；口語常用「けど」，意思相同。',quiz:{blank:'が',distractors:['から','ので','と']}},{id:'n5-g19',pattern:'〜でしょう',connection:'普通形 ＋ でしょう',meaning:'大概〜吧；〜對吧',example:{ja:'明日は雨が降るでしょう。',zh:'明天大概會下雨吧。',highlight:'降るでしょう'},tip:'推測語氣，名詞・な形容詞直接接（雨でしょう），不加だ；語尾上揚時表確認「〜對吧」。',quiz:{blank:'でしょう',distractors:['ましょう','でした','です']}},{id:'n5-g20',pattern:'〜くなる',connection:'い形容詞語幹 ＋ くなる',meaning:'變得〜',example:{ja:'春になって、暖かくなりました。',zh:'到了春天，天氣變暖和了。',highlight:'暖かくなりました'},tip:'い形容詞去い＋くなる；な形容詞・名詞則用「〜になる」（静かになる）。',quiz:{blank:'くなりました',distractors:['になりました','くしました','かったです']}},{id:'n5-g21',pattern:'〜にする',connection:'名詞 ＋ にする',meaning:'決定要〜；選〜',example:{ja:'飲み物はコーヒーにします。',zh:'飲料我要咖啡。',highlight:'コーヒーにします'},tip:'「〜にする」表說話者主動選擇或決定；「〜になる」則是自然變化或結果。',quiz:{blank:'にします',distractors:['をします','がします','でします']}},{id:'n5-g22',pattern:'〜に行く',connection:'動詞ます形／名詞 ＋ に行く',meaning:'去做〜',example:{ja:'デパートへ靴を買いに行きます。',zh:'去百貨公司買鞋子。',highlight:'買いに行きます'},tip:'目的前接動詞ます形去ます（買いに）或動作性名詞（買い物に行く）；後接行く、来る、帰る。',quiz:{blank:'に行きます',distractors:['て行きます','へ行きます','で行きます']}},{id:'n5-g23',pattern:'〜なければならない',connection:'動詞ない形（去い） ＋ ければならない',meaning:'必須〜',example:{ja:'明日は早く起きなければなりません。',zh:'明天必須早起。',highlight:'起きなければなりません'},tip:'表必須、義務；否定表「不必」時要改用「〜なくてもいい」，常成對出題。',quiz:{blank:'なければなりません',distractors:['なくてもいいです','てはいけません','なくてはいけます']}},{id:'n5-g24',pattern:'〜とき',connection:'普通形／名詞の ＋ とき',meaning:'〜的時候',example:{ja:'子どものとき、よく川で遊びました。',zh:'小時候常在河邊玩。',highlight:'子どものとき'},tip:'名詞要加の（子どものとき），な形容詞加な（ひまなとき），い形容詞直接接。',quiz:{blank:'とき',distractors:['ながら','まで','から']}},{id:'n5-g25',pattern:'〜をください',connection:'名詞 ＋ をください',meaning:'請給我〜',example:{ja:'すみません、水をください。',zh:'不好意思，請給我水。',highlight:'水をください'},tip:'向別人要東西用「名詞＋をください」；請人做動作則用「動詞て形＋ください」。',quiz:{blank:'ください',distractors:['あります','います','あげます']}},{id:'n5-g26',pattern:'〜はどうですか',connection:'名詞 ＋ はどうですか',meaning:'〜怎麼樣？',example:{ja:'明日の午後はどうですか。',zh:'明天下午怎麼樣？',highlight:'午後はどうですか'},tip:'用於詢問意見或提議；更客氣的說法是「〜はいかがですか」。',quiz:{blank:'どうですか',distractors:['どこですか','だれですか','いくらですか']}},{id:'n5-g27',pattern:'まだ〜ていない',connection:'まだ ＋ 動詞て形 ＋ いない',meaning:'還沒〜',example:{ja:'宿題はまだしていません。',zh:'作業還沒寫。',highlight:'まだしていません'},tip:'回答「もう〜ましたか」時，否定要用「いいえ、まだです／まだ〜ていません」，不可用「まだ〜ませんでした」。',quiz:{blank:'ていません',distractors:['ました','ています','てください']}},{id:'n5-g28',pattern:'〜だけ',connection:'名詞／普通形 ＋ だけ',meaning:'只有〜；只〜',example:{ja:'教室には学生が一人だけいます。',zh:'教室裡只有一個學生。',highlight:'一人だけ'},tip:'「だけ」接肯定句表只有；「しか」必須搭配否定，兩者語感不同但意思接近。',quiz:{blank:'だけ',distractors:['しか','も','ごろ']}},{id:'n5-g29',pattern:'〜しか〜ない',connection:'名詞 ＋ しか ＋ 否定',meaning:'只〜（強調少）',example:{ja:'財布に百円しかありません。',zh:'錢包裡只有一百日圓。',highlight:'百円しかありません'},tip:'「しか」後面一定要接否定形，帶有「太少」的語感，是N5常考的搭配。',quiz:{blank:'しか',distractors:['だけ','も','ごろ']}},{id:'n5-g30',pattern:'〜くて／〜で（並列）',connection:'い形容詞語幹 ＋ くて／な形容詞・名詞 ＋ で',meaning:'又〜又〜；因為〜',example:{ja:'この部屋は広くて、明るいです。',zh:'這個房間又寬敞又明亮。',highlight:'広くて'},tip:'い形容詞去い＋くて（広くて），な形容詞・名詞＋で（静かで）；「いい」變「よくて」。',quiz:{blank:'くて',distractors:['で','くで','いて']}},{id:'n5-g31',pattern:'〜のが好きだ',connection:'動詞辭書形 ＋ のが好きだ',meaning:'喜歡做〜',example:{ja:'私は料理を作るのが好きです。',zh:'我喜歡做菜。',highlight:'作るのが好きです'},tip:'動詞要先名詞化：辭書形＋の＋が好き；「〜ことが好き」也可，但不可說「〜するが好き」。',quiz:{blank:'の',distractors:['な','を','に']}},{id:'n5-g32',pattern:'〜ことができる',connection:'動詞辭書形 ＋ ことができる',meaning:'能夠〜；會〜',example:{ja:'兄はピアノを弾くことができます。',zh:'哥哥會彈鋼琴。',highlight:'弾くことができます'},tip:'表能力或可能性，與可能形意思相近（弾ける）；N5常考「名詞＋ができる」。',quiz:{blank:'ことができます',distractors:['ことがあります','ことをします','のがします']}},{id:'n5-g33',pattern:'〜や〜など',connection:'名詞 ＋ や ＋ 名詞 ＋ など',meaning:'〜和〜等等',example:{ja:'かばんの中に本やノートなどがあります。',zh:'包包裡有書和筆記本等等。',highlight:'本やノートなど'},tip:'「や」為不完全列舉（還有其他），常與「など」搭配；「と」則是完全列舉。',quiz:{blank:'や',distractors:['を','が','も']}},{id:'n5-g34',pattern:'AとBとどちらが',connection:'名詞 ＋ と ＋ 名詞 ＋ とどちらが',meaning:'A和B哪一個比較〜',example:{ja:'犬と猫とどちらが好きですか。',zh:'狗和貓你比較喜歡哪個？',highlight:'犬と猫とどちらが'},tip:'兩者比較用「どちら」，三者以上用「どれ／何／誰」；回答用「〜のほうが〜」。',quiz:{blank:'どちら',distractors:['どれ','どこ','だれ']}},{id:'n5-g35',pattern:'〜の中で〜が一番',connection:'名詞 ＋ の中で ＋ 名詞 ＋ が一番',meaning:'在〜之中〜最〜',example:{ja:'果物の中でりんごが一番好きです。',zh:'水果之中最喜歡蘋果。',highlight:'果物の中でりんごが一番'},tip:'三者以上的最高級；疑問句用「〜の中で何／どれ／誰が一番〜ですか」。',quiz:{blank:'の中で',distractors:['のほうが','より','と']}},{id:'n5-g36',pattern:'〜んです',connection:'普通形 ＋ んです（な形・名詞＋なんです）',meaning:'（說明原因、強調）是〜的',example:{ja:'頭が痛いんです。今日は休みます。',zh:'我頭很痛，今天要請假。',highlight:'痛いんです'},tip:'用於說明理由或請求解釋；名詞・な形容詞要說「〜なんです」（学生なんです）。',quiz:{blank:'んです',distractors:['ましょう','でした','だです']}},{id:'n5-g37',pattern:'〜くらい／ぐらい',connection:'數量詞 ＋ くらい／ぐらい',meaning:'大約〜',example:{ja:'駅まで十分ぐらいかかります。',zh:'到車站大約要十分鐘。',highlight:'十分ぐらい'},tip:'接在數量詞後表大約數量；表示時間點的「左右」要用「ごろ」。',quiz:{blank:'ぐらい',distractors:['ごろ','しか','など']}},{id:'n5-g38',pattern:'〜ごろ',connection:'時間名詞 ＋ ごろ',meaning:'〜左右（時間點）',example:{ja:'毎晩十一時ごろ寝ます。',zh:'每天晚上十一點左右睡覺。',highlight:'十一時ごろ'},tip:'「ごろ」用於時間點（三時ごろ）；時間長度或數量的大約用「くらい／ぐらい」。',quiz:{blank:'ごろ',distractors:['だけ','しか','など']}},{id:'n5-g39',pattern:'〜から〜まで',connection:'名詞 ＋ から ＋ 名詞 ＋ まで',meaning:'從〜到〜',example:{ja:'銀行は九時から三時までです。',zh:'銀行從九點開到三點。',highlight:'九時から三時まで'},tip:'表範圍的起點與終點，可用於時間及地點；「まで」與「までに（期限）」常被混淆。',quiz:{blank:'から',distractors:['まで','に','で']}},{id:'n5-g40',pattern:'もう〜た',connection:'もう ＋ 動詞た形',meaning:'已經〜了',example:{ja:'もう昼ご飯を食べました。',zh:'已經吃過午飯了。',highlight:'もう昼ご飯を食べました'},tip:'肯定句「もう〜ました」表已完成；否定用「まだ〜ていません」，兩者常成對考。',quiz:{blank:'もう',distractors:['まだ','ぜんぜん','あまり']}},{id:'n5-g41',pattern:'〜は（主題）',connection:'名詞 ＋ は',meaning:'提示主題：〜是／關於〜',example:{ja:'この部屋は犯人の部屋です。',zh:'這個房間是犯人的房間。',highlight:'部屋は'},tip:'「は」提示話題、表對比；疑問詞（誰、何）不可接は，要用が。',quiz:{blank:'は',distractors:['を','に','で']}},{id:'n5-g42',pattern:'〜が（主語）',connection:'名詞 ＋ が',meaning:'標示主語（新資訊、疑問詞主語）',example:{ja:'誰が窓を開けましたか。',zh:'是誰打開了窗戶？',highlight:'誰が'},tip:'疑問詞作主語時一定用「が」，回答也用が（田中さんが開けました）。',quiz:{blank:'が',distractors:['は','を','に']}},{id:'n5-g43',pattern:'〜も（也）',connection:'名詞 ＋ も',meaning:'也〜；同樣〜',example:{ja:'私も現場にいました。',zh:'我也在現場。',highlight:'私も'},tip:'「も」取代は、が、を（私も、水も飲む）；接在に、で等後則並用（ここにも）。',quiz:{blank:'も',distractors:['を','で','へ']}},{id:'n5-g44',pattern:'〜を（受詞）',connection:'名詞 ＋ を ＋ 他動詞',meaning:'標示動作的對象',example:{ja:'探偵は手紙を読みました。',zh:'偵探讀了那封信。',highlight:'手紙を'},tip:'他動詞的對象用を；「好き、わかる、ほしい、できる」等的對象則用が。',quiz:{blank:'を',distractors:['に','で','へ']}},{id:'n5-g45',pattern:'〜を（經過場所）',connection:'名詞 ＋ を ＋ 移動動詞',meaning:'經過、穿越某場所',example:{ja:'犯人はこの道を走りました。',zh:'犯人跑過了這條路。',highlight:'道を走りました'},tip:'を接移動動詞（歩く、走る、渡る）表經過的場所，不是動作的對象。',quiz:{blank:'を',distractors:['が','に','の']}},{id:'n5-g46',pattern:'〜を（離開點）',connection:'名詞 ＋ を ＋ 出る／降りる',meaning:'離開某處',example:{ja:'彼は八時に家を出ました。',zh:'他八點離開了家。',highlight:'家を出ました'},tip:'表離開的起點，常與出る、降りる、卒業する搭配；也可說「家から出る」。',quiz:{blank:'を',distractors:['に','で','が']}},{id:'n5-g47',pattern:'〜に（時間）',connection:'時間名詞 ＋ に',meaning:'在某個時間點',example:{ja:'事件は夜十時に起きました。',zh:'案件發生在晚上十點。',highlight:'十時に'},tip:'具體時間點（三時、日曜日）加に；今日、明日、毎朝等相對時間不加に。',quiz:{blank:'に',distractors:['で','を','が']}},{id:'n5-g48',pattern:'〜に（存在場所）',connection:'名詞 ＋ に ＋ ある／いる',meaning:'在某處（存在的位置）',example:{ja:'机の上に鍵があります。',zh:'桌上有鑰匙。',highlight:'机の上に'},tip:'表存在位置用に（〜にある／いる）；表動作發生地點則用で。',quiz:{blank:'に',distractors:['で','を','へ']}},{id:'n5-g49',pattern:'〜に（對象）',connection:'名詞 ＋ に',meaning:'動作的對象（給〜、對〜）',example:{ja:'警察に電話をかけました。',zh:'打了電話給警察。',highlight:'警察に'},tip:'表動作的接受者（給〜、對〜），常與あげる、電話する、会う、聞く搭配。',quiz:{blank:'に',distractors:['を','で','が']}},{id:'n5-g50',pattern:'〜に（目的地）',connection:'場所名詞 ＋ に ＋ 移動動詞',meaning:'到達某處',example:{ja:'明日、現場に行きます。',zh:'明天要去現場。',highlight:'現場に行きます'},tip:'に強調到達點；へ強調方向，與移動動詞搭配時兩者多可互換。',quiz:{blank:'に',distractors:['を','で','が']}},{id:'n5-g51',pattern:'〜へ（方向）',connection:'場所名詞 ＋ へ',meaning:'往〜（方向）',example:{ja:'男は駅へ向かいました。',zh:'那個男人往車站去了。',highlight:'駅へ'},tip:'へ作助詞時讀作「え」；接移動動詞強調方向，與に大多可互換。',quiz:{blank:'へ',distractors:['を','で','が']}},{id:'n5-g52',pattern:'〜で（動作場所）',connection:'場所名詞 ＋ で',meaning:'在某處做某事',example:{ja:'図書館で古い新聞を調べました。',zh:'在圖書館查了舊報紙。',highlight:'図書館で'},tip:'で表動作發生的場所；表存在的位置要用に（図書館にいます）。',quiz:{blank:'で',distractors:['に','を','へ']}},{id:'n5-g53',pattern:'〜で（手段）',connection:'名詞 ＋ で',meaning:'用〜；搭〜（手段、工具）',example:{ja:'犯人はタクシーで逃げました。',zh:'犯人搭計程車逃走了。',highlight:'タクシーで'},tip:'で表手段、工具或交通工具（バスで、はしで）；但「走路」說「歩いて」，不說「足で」。',quiz:{blank:'で',distractors:['を','に','が']}},{id:'n5-g54',pattern:'〜で（原因）',connection:'名詞 ＋ で',meaning:'因為〜（原因）',example:{ja:'昨日は風邪で学校を休みました。',zh:'昨天因為感冒向學校請假了。',highlight:'風邪で'},tip:'で表原因多接名詞（病気で、雨で）；接句子表理由則用「から」或「ので」。',quiz:{blank:'で',distractors:['を','に','が']}},{id:'n5-g55',pattern:'〜で（範圍）',connection:'名詞 ＋ で',meaning:'在〜範圍之內',example:{ja:'この町で一番大きい家はどれですか。',zh:'這個鎮上最大的房子是哪一棟？',highlight:'この町で'},tip:'で限定比較的範圍，常與「一番」搭配，也可用「〜の中で」。',quiz:{blank:'で一番',distractors:['を一番','へ一番','が一番']}},{id:'n5-g56',pattern:'〜で（材料）',connection:'名詞 ＋ で ＋ 作る',meaning:'用〜（材料）製作',example:{ja:'この箱は木で作りました。',zh:'這個箱子是用木頭做的。',highlight:'木で'},tip:'外觀可見原材料用「で」；原料已變質（如酒由米做成）N4以上用「から」。',quiz:{blank:'で',distractors:['を','が','へ']}},{id:'n5-g57',pattern:'〜で（合計）',connection:'數量詞 ＋ で',meaning:'合計、總共',example:{ja:'りんごは全部で五つあります。',zh:'蘋果總共有五個。',highlight:'全部で'},tip:'接在全部、みんな、一人等後，表示合計或範圍（全部で千円）。',quiz:{blank:'で',distractors:['に','を','へ']}},{id:'n5-g58',pattern:'〜と（共同）',connection:'名詞 ＋ と',meaning:'和〜一起',example:{ja:'昨日、友だちと映画を見ました。',zh:'昨天和朋友看了電影。',highlight:'友だちと'},tip:'表共同動作的對象「和〜一起」，常加「いっしょに」；可與「に」對比（友だちに会う）。',quiz:{blank:'と',distractors:['を','に','へ']}},{id:'n5-g59',pattern:'〜と（並列）',connection:'名詞 ＋ と ＋ 名詞',meaning:'〜和〜（全部列舉）',example:{ja:'部屋に男と女がいました。',zh:'房間裡有一男一女。',highlight:'男と女'},tip:'「と」為完全列舉，只有這幾項；「や」則暗示還有其他。',quiz:{blank:'と',distractors:['を','で','へ']}},{id:'n5-g60',pattern:'〜の（所屬）',connection:'名詞 ＋ の ＋ 名詞',meaning:'〜的（所屬、修飾）',example:{ja:'これは被害者の財布です。',zh:'這是被害人的錢包。',highlight:'被害者の'},tip:'名詞＋の＋名詞表所屬或修飾；な形容詞修飾名詞時用な，不用の。',quiz:{blank:'の',distractors:['が','を','に']}},{id:'n5-g61',pattern:'〜の（代名詞）',connection:'名詞／形容詞 ＋ の',meaning:'代替前面提過的名詞（〜的）',example:{ja:'この傘は私のです。',zh:'這把傘是我的。',highlight:'私のです'},tip:'の可代替前文名詞（私の傘→私の）；問「誰的」用「誰のですか」。',quiz:{blank:'のです',distractors:['がです','をです','にです']}},{id:'n5-g62',pattern:'〜か（疑問）',connection:'普通形／丁寧形 ＋ か',meaning:'表示疑問',example:{ja:'あなたは昨夜どこにいましたか。',zh:'你昨晚在哪裡？',highlight:'いましたか'},tip:'丁寧體句尾加か即成疑問句，日文一般用句號而不加問號。',quiz:{blank:'か',distractors:['ね','よ','を']}},{id:'n5-g63',pattern:'〜か（選擇）',connection:'名詞 ＋ か ＋ 名詞',meaning:'〜或〜',example:{ja:'毎朝、パンかご飯を食べます。',zh:'每天早上吃麵包或米飯。',highlight:'パンかご飯'},tip:'「AかB」表二擇一；「AとB」是兩者都有，「AやB」是舉例。',quiz:{blank:'か',distractors:['と','を','が']}},{id:'n5-g64',pattern:'〜ね',connection:'句子 ＋ ね',meaning:'〜吧；〜呢（徵求同意、感嘆）',example:{ja:'今日は寒いですね。',zh:'今天真冷呢。',highlight:'寒いですね'},tip:'ね用於徵求對方同意或確認共同認知；告訴對方不知道的事用よ。',quiz:{blank:'ね',distractors:['を','に','か']}},{id:'n5-g65',pattern:'〜よ',connection:'句子 ＋ よ',meaning:'告知對方不知道的事',example:{ja:'そのドアは開いていますよ。',zh:'那扇門是開著的喔。',highlight:'開いていますよ'},tip:'よ用於告知對方不知道的資訊、提醒；對長輩濫用會顯得強勢。',quiz:{blank:'よ',distractors:['を','か','へ']}},{id:'n5-g66',pattern:'〜から（起點）',connection:'名詞 ＋ から',meaning:'從〜（起點）',example:{ja:'銀行から男が出てきました。',zh:'有個男人從銀行走出來。',highlight:'銀行から'},tip:'から表動作的起點（地點、時間）；「出る」的起點也可用を（銀行を出る）。',quiz:{blank:'から',distractors:['へ','が','まで']}},{id:'n5-g67',pattern:'〜まで（終點）',connection:'名詞 ＋ まで',meaning:'到〜為止（終點、界限）',example:{ja:'駅まで歩いて十分です。',zh:'走到車站要十分鐘。',highlight:'駅まで'},tip:'まで表終點或界限；「までに」表期限（在〜之前完成），常被混淆。',quiz:{blank:'まで',distractors:['が','ごろ','しか']}},{id:'n5-g68',pattern:'〜は〜です',connection:'名詞 ＋ は ＋ 名詞 ＋ です',meaning:'〜是〜（肯定判斷）',example:{ja:'私は探偵です。',zh:'我是偵探。',highlight:'私は探偵です'},tip:'「AはBです」為最基本判斷句；否定形為「ではありません／じゃありません」。',quiz:{blank:'です',distractors:['ます','だ','でいます']}},{id:'n5-g69',pattern:'〜ではありません',connection:'名詞／な形容詞 ＋ ではありません',meaning:'不是〜（否定判斷）',example:{ja:'あの人は犯人ではありません。',zh:'那個人不是犯人。',highlight:'犯人ではありません'},tip:'口語可說「じゃありません」「じゃないです」；い形容詞否定不能用此形，要用「〜くないです」。',quiz:{blank:'ではありません',distractors:['くないです','がありません','ではありました']}},{id:'n5-g70',pattern:'〜でした',connection:'名詞／な形容詞 ＋ でした',meaning:'是〜（過去肯定）',example:{ja:'昨日は雨でした。',zh:'昨天是雨天。',highlight:'雨でした'},tip:'名詞・な形容詞過去用「でした」；い形容詞過去不可說「〜いでした」，要用「〜かったです」。',quiz:{blank:'でした',distractors:['かったです','ました','だです']}},{id:'n5-g71',pattern:'〜ではありませんでした',connection:'名詞／な形容詞 ＋ ではありませんでした',meaning:'不是〜（過去否定）',example:{ja:'その夜は静かではありませんでした。',zh:'那天晚上並不安靜。',highlight:'静かではありませんでした'},tip:'名詞・な形容詞的過去否定；口語可說「じゃなかったです」。',quiz:{blank:'ではありませんでした',distractors:['くなかったです','ではありました','ではないでした']}},{id:'n5-g72',pattern:'〜ます',connection:'動詞ます形 ＋ ます',meaning:'動詞的禮貌形（肯定、非過去）',example:{ja:'毎朝七時に起きます。',zh:'每天早上七點起床。',highlight:'起きます'},tip:'ます形也可表示習慣或未來（明日行きます），不只是現在。',quiz:{blank:'ます',distractors:['です','ません','たい']}},{id:'n5-g73',pattern:'〜ません',connection:'動詞ます形 ＋ ません',meaning:'動詞的禮貌形否定',example:{ja:'私はお酒を飲みません。',zh:'我不喝酒。',highlight:'飲みません'},tip:'ます形否定為「〜ません」；常體為ない形（飲まない）。',quiz:{blank:'ません',distractors:['ます','ないです','ました']}},{id:'n5-g74',pattern:'〜ました',connection:'動詞ます形 ＋ ました',meaning:'動詞的禮貌形過去',example:{ja:'犯人は裏口から逃げました。',zh:'犯人從後門逃走了。',highlight:'逃げました'},tip:'過去肯定「〜ました」；過去否定為「〜ませんでした」。',quiz:{blank:'ました',distractors:['ます','ません','でした']}},{id:'n5-g75',pattern:'〜ませんでした',connection:'動詞ます形 ＋ ませんでした',meaning:'動詞的禮貌形過去否定',example:{ja:'その夜、誰も来ませんでした。',zh:'那天晚上誰都沒來。',highlight:'来ませんでした'},tip:'過去否定，不是「〜ないでした」；「疑問詞＋も＋否定」常與此搭配考。',quiz:{blank:'ませんでした',distractors:['ました','なかったでした','ないでした']}},{id:'n5-g76',pattern:'〜いです',connection:'い形容詞 ＋ です',meaning:'い形容詞的禮貌肯定',example:{ja:'この部屋はとても暗いです。',zh:'這個房間非常暗。',highlight:'暗いです'},tip:'い形容詞直接加です，不可加だ或でした（×暗いでした）。',quiz:{blank:'です',distractors:['ます','だ','でした']}},{id:'n5-g77',pattern:'〜くないです',connection:'い形容詞（去い） ＋ くないです',meaning:'い形容詞的否定',example:{ja:'この料理は辛くないです。',zh:'這道菜不辣。',highlight:'辛くないです'},tip:'去い加くない；「いい」的否定為「よくない」，是常考例外。',quiz:{blank:'くないです',distractors:['いではありません','じゃないです','いないです']}},{id:'n5-g78',pattern:'〜かったです',connection:'い形容詞（去い） ＋ かったです',meaning:'い形容詞的過去式',example:{ja:'昨日のテストは難しかったです。',zh:'昨天的考試很難。',highlight:'難しかったです'},tip:'去い加かった＋です；「いい」的過去是「よかった」，不可說「いかった」。',quiz:{blank:'かったです',distractors:['いでした','かったでした','くでした']}},{id:'n5-g79',pattern:'〜くなかったです',connection:'い形容詞（去い） ＋ くなかったです',meaning:'い形容詞的過去否定',example:{ja:'その映画はおもしろくなかったです。',zh:'那部電影不好看。',highlight:'おもしろくなかったです'},tip:'去い加くなかった；「いい」→「よくなかったです」。',quiz:{blank:'くなかったです',distractors:['くないでした','いではありませんでした','くありませんだった']}},{id:'n5-g80',pattern:'〜な ＋ 名詞',connection:'な形容詞 ＋ な ＋ 名詞',meaning:'な形容詞修飾名詞',example:{ja:'ここは静かな町です。',zh:'這裡是個安靜的小鎮。',highlight:'静かな町'},tip:'な形容詞修飾名詞要加な；注意「きれい」「きらい」是な形容詞。',quiz:{blank:'な',distractors:['の','い','が']}},{id:'n5-g81',pattern:'〜い ＋ 名詞',connection:'い形容詞 ＋ 名詞',meaning:'い形容詞直接修飾名詞',example:{ja:'黒いかばんを持った男を見ました。',zh:'我看到一個拿著黑色包包的男人。',highlight:'黒いかばん'},tip:'い形容詞直接接名詞，不加な或の（×大きいな家）；「大きな」「小さな」為特例。',quiz:{blank:'い',distractors:['な','く','で']}},{id:'n5-g82',pattern:'〜があります',connection:'名詞 ＋ が ＋ あります',meaning:'有〜（無生命的事物）',example:{ja:'ポケットに小さいメモがあります。',zh:'口袋裡有一張小紙條。',highlight:'メモがあります'},tip:'あります用於無生命物品、植物；人或動物用います。',quiz:{blank:'あります',distractors:['います','します','なります']}},{id:'n5-g83',pattern:'〜がいます',connection:'名詞 ＋ が ＋ います',meaning:'有〜（人、動物）',example:{ja:'庭に猫がいます。',zh:'院子裡有一隻貓。',highlight:'猫がいます'},tip:'います用於人、動物等會自己動的存在；植物用あります。',quiz:{blank:'います',distractors:['あります','です','します']}},{id:'n5-g84',pattern:'〜は〜にあります',connection:'名詞 ＋ は ＋ 場所 ＋ に ＋ あります',meaning:'〜在〜（事物的所在）',example:{ja:'鍵は引き出しの中にあります。',zh:'鑰匙在抽屜裡。',highlight:'引き出しの中にあります'},tip:'「物は場所にあります」說明東西在哪；「場所に物があります」說明某處有什麼。',quiz:{blank:'あります',distractors:['います','します','なります']}},{id:'n5-g85',pattern:'〜は〜にいます',connection:'名詞 ＋ は ＋ 場所 ＋ に ＋ います',meaning:'〜在〜（人、動物的所在）',example:{ja:'田中さんは今、二階にいます。',zh:'田中先生現在在二樓。',highlight:'二階にいます'},tip:'人或動物的所在用います；問句「〜はどこにいますか」。',quiz:{blank:'います',distractors:['あります','します','なります']}},{id:'n5-g86',pattern:'〜の上に（位置）',connection:'名詞 ＋ の ＋ 上／下／中／前／後ろ／隣 ＋ に',meaning:'在〜的上面（下面、裡面等）',example:{ja:'ベッドの下に靴がありました。',zh:'床底下有一雙鞋子。',highlight:'ベッドの下に'},tip:'位置詞（上、下、中、前、後ろ、隣、近く）前接「名詞＋の」，後接に表存在位置。',quiz:{blank:'下に',distractors:['下で','下を','下へ']}},{id:'n5-g87',pattern:'〜が好きです',connection:'名詞 ＋ が ＋ 好きです',meaning:'喜歡〜',example:{ja:'私は推理小説が好きです。',zh:'我喜歡推理小說。',highlight:'推理小説が好きです'},tip:'喜好的對象用が不用を；「大好き」語氣更強。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g88',pattern:'〜が嫌いです',connection:'名詞 ＋ が ＋ 嫌いです',meaning:'討厭〜',example:{ja:'弟は野菜が嫌いです。',zh:'弟弟討厭蔬菜。',highlight:'野菜が嫌いです'},tip:'對象用が；當面直說「嫌い」語氣很強，常用「あまり好きじゃない」委婉表達。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g89',pattern:'〜が上手です',connection:'名詞 ＋ が ＋ 上手です',meaning:'擅長〜（評價他人）',example:{ja:'彼女は絵が上手です。',zh:'她很會畫畫。',highlight:'絵が上手です'},tip:'「上手」用於評價他人，說自己會時用「得意」或謙虛表達，不說「私は上手です」。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g90',pattern:'〜が下手です',connection:'名詞 ＋ が ＋ 下手です',meaning:'不擅長〜',example:{ja:'私は歌が下手です。',zh:'我唱歌很差。',highlight:'歌が下手です'},tip:'「下手」可用於自己（謙虛）；對象助詞用が。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g91',pattern:'〜がわかります',connection:'名詞 ＋ が ＋ わかります',meaning:'懂〜；知道〜',example:{ja:'犯人の名前がわかりました。',zh:'知道犯人的名字了。',highlight:'名前がわかりました'},tip:'「わかる」的對象用が，不用を；表「懂、明白」，不能用「知る」替代所有用法。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g92',pattern:'〜は〜が〜',connection:'名詞 ＋ は ＋ 名詞 ＋ が ＋ 形容詞',meaning:'〜的〜很〜（描述主題的特徵）',example:{ja:'あの男は背が高いです。',zh:'那個男人個子很高。',highlight:'男は背が高い'},tip:'大主語は＋小主語が：象は鼻が長い型，は是話題，が是描述的部位或特徵。',quiz:{blank:'が',distractors:['を','に','で']}},{id:'n5-g93',pattern:'〜て（動作順序）',connection:'動詞て形 ＋ 〜',meaning:'做〜然後做〜（依序）',example:{ja:'朝ご飯を食べて、会社へ行きました。',zh:'吃了早餐，然後去了公司。',highlight:'食べて'},tip:'用て形連接多個動作，表依序發生；時態由最後一個動詞決定。',quiz:{blank:'て',distractors:['た','る','ます']}},{id:'n5-g94',pattern:'〜なくてもいい',connection:'動詞ない形（去い） ＋ くてもいい',meaning:'不〜也可以',example:{ja:'明日は来なくてもいいです。',zh:'明天不來也可以。',highlight:'来なくてもいい'},tip:'表「不必〜」；回答「〜なければなりませんか」的否定時常用。',quiz:{blank:'なくてもいい',distractors:['なければならない','てはいけない','ないでください']}},{id:'n5-g95',pattern:'〜く（副詞）',connection:'い形容詞（去い） ＋ く ＋ 動詞',meaning:'〜地（い形容詞變副詞）',example:{ja:'もう少し早く歩いてください。',zh:'請走快一點。',highlight:'早く歩いて'},tip:'い形容詞去い＋く變副詞修飾動詞；「いい」變「よく」。',quiz:{blank:'早く',distractors:['早い','早に','早な']}},{id:'n5-g96',pattern:'〜に（副詞）',connection:'な形容詞 ＋ に ＋ 動詞',meaning:'〜地（な形容詞變副詞）',example:{ja:'子どもたちは静かに本を読んでいます。',zh:'孩子們安靜地在看書。',highlight:'静かに'},tip:'な形容詞＋に變副詞（静かに、きれいに）；修飾名詞時才用な。',quiz:{blank:'に',distractors:['な','く','の']}},{id:'n5-g97',pattern:'〜になる',connection:'名詞／な形容詞 ＋ に ＋ なる',meaning:'變成〜',example:{ja:'兄は去年、医者になりました。',zh:'哥哥去年當上了醫生。',highlight:'医者になりました'},tip:'名詞・な形容詞＋になる表變化；い形容詞則用「〜くなる」。',quiz:{blank:'に',distractors:['を','く','が']}},{id:'n5-g98',pattern:'〜くする',connection:'い形容詞（去い） ＋ く ＋ する',meaning:'把〜弄得〜',example:{ja:'部屋を明るくしてください。',zh:'請把房間弄亮一點。',highlight:'明るくして'},tip:'「〜くする」是人為使其改變（他動）；「〜くなる」是自然變化。',quiz:{blank:'くして',distractors:['にして','いして','くなって']}},{id:'n5-g99',pattern:'〜は何ですか',connection:'名詞 ＋ は ＋ 何ですか',meaning:'〜是什麼？',example:{ja:'この白い粉は何ですか。',zh:'這個白色粉末是什麼？',highlight:'何ですか'},tip:'「何」後接です、の、時等讀「なん」，接を、が時讀「なに」。',quiz:{blank:'何',distractors:['どこ','だれ','いつ']}},{id:'n5-g100',pattern:'〜はどこですか',connection:'名詞 ＋ は ＋ どこですか',meaning:'〜在哪裡？',example:{ja:'トイレはどこですか。',zh:'洗手間在哪裡？',highlight:'どこですか'},tip:'問場所用「どこ」，較禮貌的說法是「どちら」。',quiz:{blank:'どこ',distractors:['何','だれ','いつ']}},{id:'n5-g101',pattern:'〜はいつですか',connection:'名詞 ＋ は ＋ いつですか',meaning:'〜是什麼時候？',example:{ja:'あなたの誕生日はいつですか。',zh:'你的生日是什麼時候？',highlight:'いつですか'},tip:'「いつ」後面不加に（×いつに行きますか）。',quiz:{blank:'いつ',distractors:['どこ','だれ','何']}},{id:'n5-g102',pattern:'〜は誰ですか',connection:'名詞 ＋ は ＋ 誰ですか',meaning:'〜是誰？',example:{ja:'この写真の人は誰ですか。',zh:'這張照片裡的人是誰？',highlight:'誰ですか'},tip:'「誰」的禮貌說法是「どなた」；問所有者用「誰の」。',quiz:{blank:'誰',distractors:['何','どこ','いつ']}},{id:'n5-g103',pattern:'どうして〜か',connection:'どうして ＋ 普通形／丁寧形 ＋ か',meaning:'為什麼〜？',example:{ja:'どうして嘘をついたんですか。',zh:'你為什麼說謊？',highlight:'どうして'},tip:'問理由，句尾常配「〜んですか」；回答用「〜からです」。',quiz:{blank:'どうして',distractors:['どれ','だれ','いつ']}},{id:'n5-g104',pattern:'どんな〜',connection:'どんな ＋ 名詞',meaning:'什麼樣的〜',example:{ja:'犯人はどんな服を着ていましたか。',zh:'犯人穿著什麼樣的衣服？',highlight:'どんな服'},tip:'「どんな＋名詞」問性質、種類；「どの＋名詞」則是從既有選項中選一個。',quiz:{blank:'どんな',distractors:['どう','どれ','どこ']}},{id:'n5-g105',pattern:'いくら〜',connection:'いくら ＋ ですか',meaning:'多少錢',example:{ja:'このかばんはいくらですか。',zh:'這個包包多少錢？',highlight:'いくらですか'},tip:'問價格；問數量或年齡用「いくつ」，兩者常互為干擾選項。',quiz:{blank:'いくら',distractors:['いくつ','どれ','いつ']}},{id:'n5-g106',pattern:'いくつ〜',connection:'いくつ ＋ ですか／動詞',meaning:'幾個；幾歲',example:{ja:'箱の中にりんごがいくつありますか。',zh:'箱子裡有幾個蘋果？',highlight:'いくつ'},tip:'問一般物品的數量或年齡（禮貌說法「おいくつ」）；有量詞時用「何＋量詞」。',quiz:{blank:'いくつ',distractors:['いくら','どう','どの']}},{id:'n5-g107',pattern:'どれ／どの〜',connection:'どれ／どの ＋ 名詞',meaning:'哪一個；哪個〜',example:{ja:'あなたの傘はどれですか。',zh:'你的傘是哪一把？',highlight:'どれですか'},tip:'「どれ」單獨使用，三者以上選一；後面接名詞時要用「どの」。',quiz:{blank:'どれ',distractors:['どの','どんな','どう']}},{id:'n5-g108',pattern:'どうやって〜',connection:'どうやって ＋ 動詞',meaning:'怎麼做〜（方法）',example:{ja:'犯人はどうやって部屋に入りましたか。',zh:'犯人是怎麼進入房間的？',highlight:'どうやって'},tip:'問方法、手段；問原因要用「どうして」，兩者常被混淆。',quiz:{blank:'どうやって',distractors:['どんな','どれ','どの']}},{id:'n5-g109',pattern:'何 ＋ 量詞',connection:'何 ＋ 量詞（人／時／本など）',meaning:'幾〜（詢問數量、時間）',example:{ja:'今、何時ですか。',zh:'現在幾點？',highlight:'何時'},tip:'注意讀音：何時（なんじ）、何人（なんにん）、何本（なんぼん）等，常考讀法。',quiz:{blank:'何',distractors:['いくつ','どの','どんな']}},{id:'n5-g110',pattern:'疑問詞 ＋ か',connection:'疑問詞 ＋ か',meaning:'某〜（不特定的人事物）',example:{ja:'部屋の外に誰かいます。',zh:'房間外面有人。',highlight:'誰か'},tip:'疑問詞＋か表不特定（誰か、何か、どこか），肯定、否定句皆可用。',quiz:{blank:'か',distractors:['も','が','は']}},{id:'n5-g111',pattern:'疑問詞 ＋ も〜ない',connection:'疑問詞 ＋ も ＋ 否定',meaning:'什麼都（誰都、哪裡都）不〜',example:{ja:'彼は何も言いませんでした。',zh:'他什麼也沒說。',highlight:'何も言いませんでした'},tip:'疑問詞＋も＋否定表全面否定；「誰か／何か」則表示不特定的某人某物。',quiz:{blank:'も',distractors:['か','が','を']}},{id:'n5-g112',pattern:'〜はいかがですか',connection:'名詞 ＋ は ＋ いかがですか',meaning:'〜如何？（客氣地推薦）',example:{ja:'コーヒーはいかがですか。',zh:'要不要來杯咖啡？',highlight:'いかがですか'},tip:'「どう」的禮貌說法，常用於推薦或詢問對方意願（お茶はいかがですか）。',quiz:{blank:'いかが',distractors:['いくら','どれ','どこ']}},{id:'n5-g113',pattern:'〜をお願いします',connection:'名詞 ＋ を ＋ お願いします',meaning:'麻煩給我〜；拜託〜',example:{ja:'コーヒーを二つお願いします。',zh:'麻煩給我兩杯咖啡。',highlight:'お願いします'},tip:'點餐、拜託時使用，比「〜をください」更禮貌；數量詞放在を後、動詞前。',quiz:{blank:'お願いします',distractors:['あげます','あります','いきます']}},{id:'n5-g114',pattern:'〜がいいです',connection:'名詞 ＋ が ＋ いいです',meaning:'〜比較好（表示選擇）',example:{ja:'飲み物は紅茶がいいです。',zh:'飲料我要紅茶。',highlight:'紅茶がいいです'},tip:'從選項中表達自己的選擇；「〜でいい」則有「勉強可以、將就」的語感，要區分。',quiz:{blank:'が',distractors:['を','に','へ']}},{id:'n5-g115',pattern:'〜はちょっと…',connection:'名詞 ＋ は ＋ ちょっと…',meaning:'〜有點不方便（委婉拒絕）',example:{ja:'日曜日はちょっと…。',zh:'星期天有點不方便……',highlight:'ちょっと'},tip:'委婉拒絕時省略後半句，日本人常以此方式避免直接說「不行」。',quiz:{blank:'ちょっと',distractors:['とても','よく','たくさん']}},{id:'n5-g116',pattern:'〜が（開場白）',connection:'句子 ＋ が',meaning:'〜，（前言、緩和語氣）',example:{ja:'すみませんが、駅はどこですか。',zh:'不好意思，請問車站在哪裡？',highlight:'すみませんが'},tip:'放在請求或提問前的前言，緩和語氣，不表示轉折；常見「すみませんが」「失礼ですが」。',quiz:{blank:'が',distractors:['を','に','から']}},{id:'n5-g117',pattern:'〜けれども',connection:'普通形／丁寧形 ＋ けれども',meaning:'雖然〜但是〜',example:{ja:'この店は高いけれども、おいしいです。',zh:'這家店雖然貴，但很好吃。',highlight:'高いけれども'},tip:'與逆接「が」同義；口語縮約為「けど」「けれど」。',quiz:{blank:'けれども',distractors:['から','ので','と']}},{id:'n5-g118',pattern:'それから〜',connection:'句子。 ＋ それから ＋ 句子',meaning:'然後〜；接著〜',example:{ja:'手紙を読みました。それから、警察に電話しました。',zh:'讀了信，接著打電話給警察。',highlight:'それから'},tip:'表動作或事情的先後順序；也可用於追加「還有」。',quiz:{blank:'それから',distractors:['でも','だから','どうして']}},{id:'n5-g119',pattern:'そして〜',connection:'句子。 ＋ そして ＋ 句子',meaning:'而且〜；然後〜',example:{ja:'彼は背が高いです。そして、目が青いです。',zh:'他個子高，而且眼睛是藍色的。',highlight:'そして'},tip:'表單純並列或順序；「でも」表轉折，「だから」表因果，常互為選項。',quiz:{blank:'そして',distractors:['でも','だから','どうして']}},{id:'n5-g120',pattern:'でも〜',connection:'句子。 ＋ でも ＋ 句子',meaning:'可是〜；但是〜',example:{ja:'窓は閉まっていました。でも、鍵は開いていました。',zh:'窗戶是關著的，可是鎖是開的。',highlight:'でも'},tip:'用於句首表轉折，比「しかし」口語；句中逆接要用「が」或「けど」。',quiz:{blank:'でも',distractors:['そして','それから','だから']}}]},1231,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N5_READING",{enumerable:!0,get:function(){return n}});const n=[{id:"n5-r01",title:"私の朝",titleZh:"我的早晨",topic:"生活",paragraphs:[{ja:"私は毎朝六時に起きます。まず、顔を洗って、歯をみがきます。それから、台所で朝ご飯を作ります。",zh:"我每天早上六點起床。首先洗臉、刷牙。然後在廚房做早餐。"},{ja:"朝ご飯はたいていパンと卵です。牛乳も飲みます。でも、日曜日はご飯とみそしるを食べます。",zh:"早餐通常是麵包和蛋。也會喝牛奶。不過，星期天會吃白飯和味噌湯。"},{ja:"七時半に家を出ます。駅まで十分ぐらい歩きます。電車の中で、本を読みます。会社は九時からです。朝は少し忙しいですが、私の好きな時間です。",zh:"七點半出門。走路到車站大約十分鐘。在電車上看書。公司九點開始上班。早上有點忙，但是我喜歡的時間。"}],vocab:[{word:"毎朝",reading:"まいあさ",meaning:"每天早上"},{word:"起きる",reading:"おきる",meaning:"起床"},{word:"洗う",reading:"あらう",meaning:"洗"},{word:"台所",reading:"だいどころ",meaning:"廚房"},{word:"卵",reading:"たまご",meaning:"蛋"},{word:"牛乳",reading:"ぎゅうにゅう",meaning:"牛奶"},{word:"忙しい",reading:"いそがしい",meaning:"忙碌的"}],questions:[{question:"この人は朝ご飯に、たいてい何を食べますか。",questionZh:"這個人早餐通常吃什麼？",options:["パンと卵","ご飯とみそしる","パンと肉","卵と魚"]},{question:"この人は何時に家を出ますか。",questionZh:"這個人幾點出門？",options:["七時半","六時","九時","七時"]}]},{id:"n5-r02",title:"お正月",titleZh:"新年",topic:"文化",paragraphs:[{ja:"一月一日はお正月です。日本では、お正月はとても大切な日です。たくさんの人が家族といっしょに休みます。",zh:"一月一日是新年。在日本，新年是非常重要的日子。很多人會和家人一起休息。"},{ja:"お正月には、「おせち」という料理を食べます。おもちも食べます。子どもは大人からお金をもらいます。これは「お年玉」です。",zh:"新年時會吃一種叫「御節料理」的菜。也會吃年糕。小孩會從大人那裡拿到錢。這就是「壓歲錢」。"},{ja:"私の家族は毎年、近くの神社へ行きます。今年は天気がよかったですが、とても寒かったです。神社のあと、家でみんなでテレビを見ました。",zh:"我的家人每年都會去附近的神社。今年天氣很好，但是非常冷。去完神社後，大家在家裡一起看電視。"}],vocab:[{word:"正月",reading:"しょうがつ",meaning:"新年、正月"},{word:"大切",reading:"たいせつ",meaning:"重要"},{word:"家族",reading:"かぞく",meaning:"家人"},{word:"料理",reading:"りょうり",meaning:"料理、菜餚"},{word:"大人",reading:"おとな",meaning:"大人"},{word:"毎年",reading:"まいとし",meaning:"每年"},{word:"寒い",reading:"さむい",meaning:"寒冷的"}],questions:[{question:"お正月に、子どもは大人から何をもらいますか。",questionZh:"新年時，小孩會從大人那裡拿到什麼？",options:["お金","おもち","おせち","本"]},{question:"今年のお正月の天気はどうでしたか。",questionZh:"今年新年的天氣如何？",options:["よかったですが、寒かったです","雨が降りました","暖かかったです","雪がたくさん降りました"]}]},{id:"n5-r03",title:"土曜日の買い物",titleZh:"星期六的購物",topic:"生活",paragraphs:[{ja:"土曜日の午後、私は母と駅の前のスーパーへ行きました。スーパーはとても大きくて、人がたくさんいました。",zh:"星期六下午，我和媽媽去了車站前面的超市。超市非常大，人很多。"},{ja:"まず、野菜を買いました。トマトとたまねぎです。それから、肉と魚も買いました。りんごは高かったですから、買いませんでした。",zh:"首先買了蔬菜，是番茄和洋蔥。然後也買了肉和魚。蘋果很貴，所以沒有買。"},{ja:"全部で三千円でした。帰りに、喫茶店でコーヒーを飲みました。夜、母と二人でカレーを作りました。とてもおいしかったです。",zh:"全部是三千日圓。回家的路上，在咖啡店喝了咖啡。晚上，我和媽媽兩個人一起做了咖哩。非常好吃。"}],vocab:[{word:"午後",reading:"ごご",meaning:"下午"},{word:"野菜",reading:"やさい",meaning:"蔬菜"},{word:"肉",reading:"にく",meaning:"肉"},{word:"魚",reading:"さかな",meaning:"魚"},{word:"高い",reading:"たかい",meaning:"貴的、高的"},{word:"全部",reading:"ぜんぶ",meaning:"全部"},{word:"喫茶店",reading:"きっさてん",meaning:"咖啡店"}],questions:[{question:"どうしてりんごを買いませんでしたか。",questionZh:"為什麼沒有買蘋果？",options:["高かったからです","店になかったからです","母がきらいだからです","重かったからです"]},{question:"夜、二人は何を作りましたか。",questionZh:"晚上兩個人做了什麼？",options:["カレー","サラダ","魚の料理","ケーキ"]}]},{id:"n5-r04",title:"日本の四つの季節",titleZh:"日本的四季",topic:"自然",paragraphs:[{ja:"日本には四つの季節があります。春、夏、秋、冬です。季節によって、天気や食べ物がちがいます。",zh:"日本有四個季節：春、夏、秋、冬。依照季節不同，天氣和食物也不一樣。"},{ja:"春は暖かいです。三月と四月に、きれいな桜の花がさきます。夏はとても暑いです。海や山へ行く人が多いです。",zh:"春天很溫暖。三月和四月會開漂亮的櫻花。夏天非常熱。很多人會去海邊或山上。"},{ja:"秋はすずしいです。木の葉が赤や黄色になります。冬は寒いです。北の町では、雪がたくさん降ります。",zh:"秋天很涼爽。樹葉會變成紅色或黃色。冬天很冷。北方的城鎮會下很多雪。"},{ja:"私は秋がいちばん好きです。食べ物がおいしいですから。",zh:"我最喜歡秋天。因為食物很好吃。"}],vocab:[{word:"季節",reading:"きせつ",meaning:"季節"},{word:"暖かい",reading:"あたたかい",meaning:"溫暖的"},{word:"桜",reading:"さくら",meaning:"櫻花"},{word:"暑い",reading:"あつい",meaning:"（天氣）熱的"},{word:"葉",reading:"は",meaning:"葉子"},{word:"雪",reading:"ゆき",meaning:"雪"},{word:"降る",reading:"ふる",meaning:"（雨、雪）下、降"}],questions:[{question:"桜の花はいつさきますか。",questionZh:"櫻花什麼時候開？",options:["三月と四月","七月と八月","十月と十一月","十二月と一月"]},{question:"秋に、木の葉はどうなりますか。",questionZh:"秋天時，樹葉會變得怎麼樣？",options:["赤や黄色になります","白くなります","青くなります","大きくなります"]},{question:"この人はどうして秋が好きですか。",questionZh:"這個人為什麼喜歡秋天？",options:["食べ物がおいしいからです","雪が降るからです","海へ行くからです","桜がきれいだからです"]}]},{id:"n5-r05",title:"日本の電車",titleZh:"日本的電車",topic:"社會",paragraphs:[{ja:"日本の大きい町には、電車がたくさんあります。東京では、毎日たくさんの人が電車で会社や学校へ行きます。",zh:"日本的大城市有很多電車。在東京，每天有很多人搭電車去公司或學校。"},{ja:"朝の電車はとても込んでいます。でも、電車の中では、みんな静かです。電話で話す人はあまりいません。",zh:"早上的電車非常擁擠。不過，在電車裡大家都很安靜。幾乎沒有人講電話。"},{ja:"日本の電車はあまり遅れません。でも、雨や雪の日は、ときどき遅れます。駅には、店やレストランもあって、とても便利です。",zh:"日本的電車很少誤點。但是下雨或下雪的日子，有時候會誤點。車站裡也有商店和餐廳，非常方便。"}],vocab:[{word:"電車",reading:"でんしゃ",meaning:"電車"},{word:"毎日",reading:"まいにち",meaning:"每天"},{word:"会社",reading:"かいしゃ",meaning:"公司"},{word:"静か",reading:"しずか",meaning:"安靜"},{word:"電話",reading:"でんわ",meaning:"電話"},{word:"駅",reading:"えき",meaning:"車站"},{word:"便利",reading:"べんり",meaning:"方便"}],questions:[{question:"電車の中で、人はどうですか。",questionZh:"在電車裡，人們是什麼樣子？",options:["静かです","電話でたくさん話します","歌を歌います","大きい声で話します"]},{question:"電車はどんな日に、ときどき遅れますか。",questionZh:"電車在什麼樣的日子有時候會誤點？",options:["雨や雪の日","日曜日","暑い日","休みの日"]}]},{id:"n5-r06",title:"夜の空の月",titleZh:"夜空中的月亮",topic:"科學",paragraphs:[{ja:"夜、空を見てください。月が見えますか。月の形は毎日少しずつ変わります。丸い日も、細い日もあります。",zh:"晚上請看看天空。看得到月亮嗎？月亮的形狀每天一點一點地改變。有圓的日子，也有細細的日子。"},{ja:"月は自分で光りません。太陽の光で、月は明るく見えます。",zh:"月亮自己不會發光。因為太陽的光，月亮看起來才是亮的。"},{ja:"月は地球からとても遠いです。月には空気も水もありません。ですから、人や動物は月に住むことができません。いつか月へ行ってみたいですね。",zh:"月亮離地球非常遠。月亮上沒有空氣，也沒有水。所以人和動物無法住在月亮上。真想有一天去月亮看看呢。"}],vocab:[{word:"空",reading:"そら",meaning:"天空"},{word:"形",reading:"かたち",meaning:"形狀"},{word:"丸い",reading:"まるい",meaning:"圓的"},{word:"細い",reading:"ほそい",meaning:"細的"},{word:"太陽",reading:"たいよう",meaning:"太陽"},{word:"明るい",reading:"あかるい",meaning:"明亮的"},{word:"遠い",reading:"とおい",meaning:"遠的"},{word:"動物",reading:"どうぶつ",meaning:"動物"}],questions:[{question:"月はどうして明るく見えますか。",questionZh:"月亮為什麼看起來是亮的？",options:["太陽の光があるからです","月が自分で光るからです","月に水があるからです","月が地球から近いからです"]},{question:"月について、正しいものはどれですか。",questionZh:"關於月亮，哪一個是正確的？",options:["空気がありません","動物が住んでいます","形は変わりません","地球から近いです"]}]},{id:"n5-r07",title:"はしの使い方",titleZh:"筷子的用法",topic:"文化",paragraphs:[{ja:"日本人はご飯を食べるとき、はしを使います。はしは二本の細い木です。",zh:"日本人吃飯的時候會用筷子。筷子是兩根細細的木頭。"},{ja:"子どもは小さいとき、家ではしの持ち方を習います。はじめは難しいですが、毎日使いますから、だんだん上手になります。",zh:"小孩小時候會在家裡學拿筷子的方法。一開始很難，但是因為每天都用，所以會漸漸變得很拿手。"},{ja:"はしには、ルールもあります。たとえば、ご飯にはしを立てません。それから、はしで人をさしません。",zh:"筷子也有規矩。例如，不會把筷子插在飯上。還有，不會用筷子指人。"},{ja:"先月、私は外国人の友だちにはしの使い方を教えました。友だちは今、とても上手です。",zh:"上個月，我教外國朋友用筷子的方法。朋友現在用得非常好。"}],vocab:[{word:"使う",reading:"つかう",meaning:"使用"},{word:"習う",reading:"ならう",meaning:"學習"},{word:"難しい",reading:"むずかしい",meaning:"困難的"},{word:"上手",reading:"じょうず",meaning:"擅長、拿手"},{word:"立てる",reading:"たてる",meaning:"立起來、豎立"},{word:"外国人",reading:"がいこくじん",meaning:"外國人"},{word:"教える",reading:"おしえる",meaning:"教"}],questions:[{question:"はしについて、文と合うものはどれですか。",questionZh:"關於筷子，哪一個和文章內容相符？",options:["ご飯にはしを立てません","はしで人をさしてもいいです","はしは三本の木です","子どもは大人になってから習います"]},{question:"「私」はだれにはしの使い方を教えましたか。",questionZh:"「我」教了誰筷子的用法？",options:["外国人の友だち","小さい子ども","学校の先生","母"]}]},{id:"n5-r08",title:"公園の鳥",titleZh:"公園裡的鳥",topic:"自然",paragraphs:[{ja:"私の家の近くに、大きい公園があります。公園には池があって、木もたくさんあります。",zh:"我家附近有一座大公園。公園裡有池塘，也有很多樹。"},{ja:"毎朝、私は犬と公園を散歩します。朝の公園では、いろいろな鳥が鳴いています。木の上には小さい鳥がいます。池には白い鳥がいます。",zh:"每天早上，我帶狗在公園散步。早上的公園裡，各種鳥在叫。樹上有小鳥。池塘裡有白色的鳥。"},{ja:"先週の日曜日、池で魚を食べている大きい鳥を見ました。とてもびっくりしました。写真をとって、弟に見せました。",zh:"上星期天，我看到一隻大鳥在池塘裡吃魚。我非常驚訝。我拍了照片，給弟弟看。"}],vocab:[{word:"公園",reading:"こうえん",meaning:"公園"},{word:"池",reading:"いけ",meaning:"池塘"},{word:"散歩",reading:"さんぽ",meaning:"散步"},{word:"鳥",reading:"とり",meaning:"鳥"},{word:"鳴く",reading:"なく",meaning:"（鳥、動物）叫、鳴叫"},{word:"先週",reading:"せんしゅう",meaning:"上星期"},{word:"写真",reading:"しゃしん",meaning:"照片"},{word:"弟",reading:"おとうと",meaning:"弟弟"}],questions:[{question:"池には、どんな鳥がいますか。",questionZh:"池塘裡有什麼樣的鳥？",options:["白い鳥","黄色い鳥","青い鳥","黒い鳥"]},{question:"先週の日曜日、「私」は何を見ましたか。",questionZh:"上星期天，「我」看到了什麼？",options:["魚を食べている大きい鳥","池で泳いでいる犬","木の上の猫","大きい魚"]}]},{id:"n5-r09",title:"新しい図書館",titleZh:"新的圖書館",topic:"社會",paragraphs:[{ja:"私の町には、新しい図書館があります。去年できました。駅から歩いて五分です。",zh:"我住的城鎮有一間新的圖書館。是去年蓋好的。從車站走路五分鐘。"},{ja:"図書館には、本や雑誌がたくさんあります。子どもの本の部屋もあります。本は一回に十冊まで借りることができます。二週間で返します。",zh:"圖書館裡有很多書和雜誌。也有兒童書的房間。書一次最多可以借十本。兩個星期內要還。"},{ja:"図書館の中では、大きい声で話してはいけません。食べ物も食べてはいけません。でも、二階の部屋では飲み物を飲んでもいいです。",zh:"在圖書館裡不可以大聲說話。也不可以吃東西。但是，在二樓的房間可以喝飲料。"},{ja:"図書館はお金がいりません。だれでも使うことができます。",zh:"圖書館不用錢。任何人都可以使用。"}],vocab:[{word:"図書館",reading:"としょかん",meaning:"圖書館"},{word:"去年",reading:"きょねん",meaning:"去年"},{word:"雑誌",reading:"ざっし",meaning:"雜誌"},{word:"借りる",reading:"かりる",meaning:"借（入）"},{word:"返す",reading:"かえす",meaning:"歸還"},{word:"声",reading:"こえ",meaning:"聲音"},{word:"飲み物",reading:"のみもの",meaning:"飲料"}],questions:[{question:"本は一回に何冊まで借りることができますか。",questionZh:"書一次最多可以借幾本？",options:["十冊","五冊","二冊","十二冊"]},{question:"図書館について、正しいものはどれですか。",questionZh:"關於圖書館，哪一個是正確的？",options:["二階の部屋で飲み物を飲んでもいいです","使うとき、お金がいります","駅から歩いて十分です","本は一か月で返します"]}]},{id:"n5-r10",title:"なくなったケーキ",titleZh:"不見的蛋糕",topic:"推理",paragraphs:[{ja:"日曜日の午後、母が冷蔵庫にケーキを入れました。でも、夜、ケーキはありませんでした。午後、家には父と兄と妹がいました。",zh:"星期天下午，媽媽把蛋糕放進冰箱。但是到了晚上，蛋糕不見了。下午家裡有爸爸、哥哥和妹妹。"},{ja:"母は三人に聞きました。父は「私は午後ずっと外で車を洗っていました」と言いました。兄は「私は部屋で勉強していました。甘いものはきらいです」と言いました。妹は「私は知りません」と言いました。",zh:"媽媽問了三個人。爸爸說：「我下午一直在外面洗車。」哥哥說：「我在房間讀書。我討厭甜的東西。」妹妹說：「我不知道。」"},{ja:"私は小さい探偵です。妹の顔をよく見ました。妹の口の近くに、白いクリームが少しありました。私はすぐわかりました。",zh:"我是小偵探。我仔細看了妹妹的臉。妹妹的嘴巴旁邊有一點白色的奶油。我馬上就知道了。"}],vocab:[{word:"冷蔵庫",reading:"れいぞうこ",meaning:"冰箱"},{word:"兄",reading:"あに",meaning:"哥哥"},{word:"妹",reading:"いもうと",meaning:"妹妹"},{word:"勉強",reading:"べんきょう",meaning:"讀書、學習"},{word:"甘い",reading:"あまい",meaning:"甜的"},{word:"探偵",reading:"たんてい",meaning:"偵探"},{word:"口",reading:"くち",meaning:"嘴巴"}],questions:[{question:"兄は午後、何をしていましたか。",questionZh:"哥哥下午在做什麼？",options:["部屋で勉強していました","外で車を洗っていました","ケーキを作っていました","公園で遊んでいました"]},{question:"ケーキを食べたのはだれですか。",questionZh:"吃掉蛋糕的是誰？",options:["妹","父","兄","母"]}]},{id:"n5-r11",title:"だれの傘",titleZh:"是誰的傘",topic:"推理",paragraphs:[{ja:"雨の日、教室に青い傘が一本ありました。名前はありませんでした。先生は「これはだれの傘ですか」と聞きました。",zh:"下雨天，教室裡有一把藍色的傘。上面沒有名字。老師問：「這是誰的傘？」"},{ja:"三人が「私のです」と言いました。田中さんは「私の傘は青くて、長いです」と言いました。山田さんは「私の傘は青くて、新しいです」と言いました。鈴木さんは「私の傘は青くて、中に黄色い花の絵があります」と言いました。",zh:"有三個人說：「是我的。」田中說：「我的傘是藍色的，很長。」山田說：「我的傘是藍色的，是新的。」鈴木說：「我的傘是藍色的，裡面有黃色的花的圖案。」"},{ja:"先生は傘を開きました。中に小さい黄色い花の絵がありました。それに、この傘は古くて、短い傘でした。",zh:"老師把傘打開。裡面有小小的黃色花朵圖案。而且，這把傘是又舊又短的傘。"}],vocab:[{word:"教室",reading:"きょうしつ",meaning:"教室"},{word:"傘",reading:"かさ",meaning:"傘"},{word:"名前",reading:"なまえ",meaning:"名字"},{word:"長い",reading:"ながい",meaning:"長的"},{word:"黄色い",reading:"きいろい",meaning:"黃色的"},{word:"古い",reading:"ふるい",meaning:"舊的"},{word:"短い",reading:"みじかい",meaning:"短的"}],questions:[{question:"先生が傘を開くと、中に何がありましたか。",questionZh:"老師打開傘之後，裡面有什麼？",options:["小さい黄色い花の絵","名前","青い花の絵","小さい写真"]},{question:"この傘はだれの傘ですか。",questionZh:"這把傘是誰的傘？",options:["鈴木さん","田中さん","山田さん","先生"]}]},{id:"n5-r12",title:"雪の日の手紙",titleZh:"下雪天的信",topic:"推理",paragraphs:[{ja:"朝、雪がたくさん降りました。山田さんの家のドアの前に、手紙が一つありました。ひらがなで「おたんじょうび おめでとう」と書いてありました。でも、名前はありませんでした。",zh:"早上下了很多雪。山田先生家門口有一封信。上面用平假名寫著「生日快樂」。但是沒有寫名字。"},{ja:"雪の上に、小さい足あとがありました。足あとは、となりの家から来ていました。",zh:"雪地上有小小的腳印。腳印是從隔壁家過來的。"},{ja:"となりの家には、三人がいます。背が高いおじいさんと、お母さんと、六歳の男の子です。男の子はよく山田さんと遊びます。",zh:"隔壁家住著三個人。個子很高的爺爺、媽媽，還有六歲的男孩。男孩常常和山田先生一起玩。"},{ja:"山田さんは「わかりました」と言って、ほほえみました。そして、となりの家へ行きました。",zh:"山田先生說：「我知道了。」然後露出了微笑。接著，他去了隔壁家。"}],vocab:[{word:"雪",reading:"ゆき",meaning:"雪"},{word:"手紙",reading:"てがみ",meaning:"信"},{word:"足",reading:"あし",meaning:"腳"},{word:"となり",reading:"となり",meaning:"隔壁、旁邊"},{word:"背",reading:"せ",meaning:"身高、個子"},{word:"男の子",reading:"おとこのこ",meaning:"男孩"},{word:"遊ぶ",reading:"あそぶ",meaning:"玩"}],questions:[{question:"足あとは、どこから来ていましたか。",questionZh:"腳印是從哪裡來的？",options:["となりの家","駅","学校","公園"]},{question:"手紙を書いたのはだれだと思いますか。",questionZh:"你認為寫信的是誰？",options:["となりの家の男の子","背が高いおじいさん","となりの家のお母さん","山田さん"]}]},{id:"n5-r13",title:"友だちの誕生日",titleZh:"朋友的生日",topic:"生活",paragraphs:[{ja:"先週の金曜日は、友だちの木村さんの誕生日でした。夕方、私はほかの友だちと木村さんの家へ行きました。",zh:"上星期五是朋友木村的生日。傍晚，我和其他朋友一起去了木村家。"},{ja:"私はプレゼントに青いぼうしを買いました。木村さんは「ありがとう。青は私の好きな色です」と言って、すぐそのぼうしをかぶりました。",zh:"我買了一頂藍色的帽子當禮物。木村說：「謝謝。藍色是我喜歡的顏色。」然後馬上戴上了那頂帽子。"},{ja:"木村さんのお母さんが、カレーとサラダを作りました。大きいケーキもありました。みんなで歌を歌って、ケーキを食べました。",zh:"木村的媽媽做了咖哩和沙拉。還有一個大蛋糕。大家一起唱了歌，吃了蛋糕。"},{ja:"九時ごろ、家へ帰りました。とても楽しい夜でした。",zh:"九點左右回到家。那是一個非常開心的夜晚。"}],vocab:[{word:"誕生日",reading:"たんじょうび",meaning:"生日"},{word:"夕方",reading:"ゆうがた",meaning:"傍晚"},{word:"青い",reading:"あおい",meaning:"藍色的"},{word:"ぼうし",reading:"ぼうし",meaning:"帽子"},{word:"かぶる",reading:"かぶる",meaning:"戴（帽子）"},{word:"歌う",reading:"うたう",meaning:"唱（歌）"},{word:"帰る",reading:"かえる",meaning:"回去、回家"},{word:"楽しい",reading:"たのしい",meaning:"快樂的、開心的"}],questions:[{question:"「私」は木村さんに何をあげましたか。",questionZh:"「我」送了木村什麼？",options:["青いぼうし","赤いぼうし","青いかばん","大きいケーキ"]},{question:"カレーとサラダを作ったのはだれですか。",questionZh:"做咖哩和沙拉的是誰？",options:["木村さんのお母さん","木村さん","「私」","木村さんのお父さん"]}]},{id:"n5-r14",title:"かぜをひいた日",titleZh:"感冒的那一天",topic:"生活",paragraphs:[{ja:"きのうの朝、私は頭が痛くて、のども痛かったです。熱も少しありました。かぜをひきました。",zh:"昨天早上，我頭很痛，喉嚨也很痛。也有一點發燒。我感冒了。"},{ja:"私は会社を休んで、近くの病院へ行きました。医者は「この薬を飲んで、今日はたくさん寝てください」と言いました。",zh:"我向公司請了假，去了附近的醫院。醫生說：「請吃這個藥，今天要好好睡覺。」"},{ja:"家に帰って、薬を飲んで寝ました。夜、姉がりんごとジュースを持ってきました。姉はとてもやさしいです。",zh:"回到家後，吃了藥就睡了。晚上，姊姊帶了蘋果和果汁來。姊姊非常溫柔。"},{ja:"今朝はもう元気です。でも、今日は暖かい服を着て、会社へ行きます。",zh:"今天早上已經恢復精神了。不過，今天要穿暖和的衣服去公司。"}],vocab:[{word:"頭",reading:"あたま",meaning:"頭"},{word:"痛い",reading:"いたい",meaning:"痛的"},{word:"休む",reading:"やすむ",meaning:"休息、請假"},{word:"病院",reading:"びょういん",meaning:"醫院"},{word:"医者",reading:"いしゃ",meaning:"醫生"},{word:"薬",reading:"くすり",meaning:"藥"},{word:"寝る",reading:"ねる",meaning:"睡覺"},{word:"元気",reading:"げんき",meaning:"有精神、健康"}],questions:[{question:"医者は何と言いましたか。",questionZh:"醫生說了什麼？",options:["薬を飲んで、寝てください","会社へ行ってください","たくさん食べてください","外を散歩してください"]},{question:"夜、姉は何を持ってきましたか。",questionZh:"晚上，姊姊帶了什麼來？",options:["りんごとジュース","薬と水","パンと牛乳","花と本"]}]},{id:"n5-r15",title:"日本のおふろ",titleZh:"日本的泡澡",topic:"文化",paragraphs:[{ja:"日本人はおふろが大好きです。たいてい毎晩、おふろに入ります。暑い夏も、おふろに入る人が多いです。",zh:"日本人非常喜歡泡澡。通常每天晚上都會泡澡。即使是炎熱的夏天，泡澡的人也很多。"},{ja:"日本のおふろでは、まず体を洗います。それから、お湯に入ります。お湯の中で体を洗ってはいけません。",zh:"在日本泡澡時，首先要洗身體。然後才進到熱水裡。不可以在熱水裡洗身體。"},{ja:"家族はみんな同じお湯に入ります。ですから、お湯をきれいに使います。",zh:"家人都泡同一缸熱水。所以，使用熱水時要保持乾淨。"},{ja:"町には、大きいおふろの店もあります。「銭湯」といいます。私は週末、ときどき父と銭湯へ行きます。広いおふろはとても気持ちがいいです。",zh:"城鎮裡也有大型的澡堂，叫做「錢湯」。我週末有時候會和爸爸去錢湯。寬敞的浴池非常舒服。"}],vocab:[{word:"毎晩",reading:"まいばん",meaning:"每天晚上"},{word:"体",reading:"からだ",meaning:"身體"},{word:"洗う",reading:"あらう",meaning:"洗"},{word:"お湯",reading:"おゆ",meaning:"熱水"},{word:"同じ",reading:"おなじ",meaning:"相同的、同一個"},{word:"店",reading:"みせ",meaning:"店"},{word:"週末",reading:"しゅうまつ",meaning:"週末"},{word:"広い",reading:"ひろい",meaning:"寬敞的"}],questions:[{question:"日本のおふろでは、まず何をしますか。",questionZh:"在日本泡澡時，首先要做什麼？",options:["体を洗います","お湯に入ります","水を飲みます","歯をみがきます"]},{question:"「銭湯」は何ですか。",questionZh:"「錢湯」是什麼？",options:["町にある大きいおふろの店","家の中の小さいおふろ","おふろのあとで飲む物","体を洗うときに使う物"]}]},{id:"n5-r16",title:"日本のコンビニ",titleZh:"日本的便利商店",topic:"社會",paragraphs:[{ja:"日本には、コンビニがたくさんあります。駅の近くにも、学校の近くにもあります。たいていの店は二十四時間開いています。",zh:"日本有很多便利商店。車站附近有，學校附近也有。大部分的店都是二十四小時營業。"},{ja:"コンビニでは、おにぎりやお弁当、飲み物、雑誌などを売っています。朝は、会社へ行く人がたくさん来ます。",zh:"便利商店有賣飯糰、便當、飲料、雜誌等等。早上會有很多要去公司的人來。"},{ja:"食べ物のほかに、切手やはがきも買うことができます。荷物を送ることもできます。",zh:"除了食物以外，也可以買郵票和明信片。還可以寄包裹。"},{ja:"私の家の近くのコンビニは、夜も明るくて、とても便利です。でも、物はスーパーより少し高いです。",zh:"我家附近的便利商店晚上也很明亮，非常方便。不過，東西比超市貴一點。"}],vocab:[{word:"開く",reading:"あく",meaning:"開（門）、營業"},{word:"お弁当",reading:"おべんとう",meaning:"便當"},{word:"売る",reading:"うる",meaning:"賣"},{word:"切手",reading:"きって",meaning:"郵票"},{word:"はがき",reading:"はがき",meaning:"明信片"},{word:"荷物",reading:"にもつ",meaning:"行李、包裹"},{word:"送る",reading:"おくる",meaning:"寄送"},{word:"便利",reading:"べんり",meaning:"方便"}],questions:[{question:"コンビニで、何ができますか。",questionZh:"在便利商店可以做什麼？",options:["切手を買うことができます","電車に乗ることができます","本を借りることができます","料理を習うことができます"]},{question:"「私」の家の近くのコンビニについて、正しいものはどれですか。",questionZh:"關於「我」家附近的便利商店，哪一個是正確的？",options:["スーパーより少し高いです","スーパーより安いです","夜は開いていません","駅の中にあります"]}]},{id:"n5-r17",title:"富士山",titleZh:"富士山",topic:"自然",paragraphs:[{ja:"富士山は日本でいちばん高い山です。高さは三千七百七十六メートルです。",zh:"富士山是日本最高的山。高度是三千七百七十六公尺。"},{ja:"富士山は東京からあまり遠くありません。天気がいい日は、東京からも富士山が見えます。",zh:"富士山離東京不太遠。天氣好的日子，從東京也看得到富士山。"},{ja:"冬は、山の上が雪で白くなります。夏は雪があまりありません。七月と八月には、たくさんの人が富士山に登ります。",zh:"冬天，山頂會因為積雪而變白。夏天雪不多。七月和八月，很多人會去爬富士山。"},{ja:"去年の夏、私も家族と富士山に登りました。山の上はとても寒かったです。でも、朝の太陽がとてもきれいでした。",zh:"去年夏天，我也和家人一起爬了富士山。山頂非常冷。但是早上的太陽非常美。"}],vocab:[{word:"高い",reading:"たかい",meaning:"高的"},{word:"見える",reading:"みえる",meaning:"看得見"},{word:"冬",reading:"ふゆ",meaning:"冬天"},{word:"白い",reading:"しろい",meaning:"白色的"},{word:"夏",reading:"なつ",meaning:"夏天"},{word:"登る",reading:"のぼる",meaning:"爬、攀登"},{word:"去年",reading:"きょねん",meaning:"去年"},{word:"太陽",reading:"たいよう",meaning:"太陽"}],questions:[{question:"天気がいい日について、正しいものはどれですか。",questionZh:"關於天氣好的日子，哪一個是正確的？",options:["東京から富士山が見えます","富士山に雪が降ります","東京がとても寒くなります","富士山に登ることができません"]},{question:"たくさんの人が富士山に登るのは、いつですか。",questionZh:"很多人去爬富士山是在什麼時候？",options:["七月と八月","一月と二月","三月と四月","十月と十一月"]},{question:"去年の夏、山の上はどうでしたか。",questionZh:"去年夏天，山頂怎麼樣？",options:["とても寒かったです","とても暑かったです","雨が降っていました","人がいませんでした"]}]},{id:"n5-r18",title:"水と雲",titleZh:"水和雲",topic:"科學",paragraphs:[{ja:"冬の寒い朝、池に氷がありました。とても寒い日には、水は氷になります。",zh:"冬天一個寒冷的早上，池塘裡結了冰。在非常冷的日子，水會變成冰。"},{ja:"氷は水より軽いです。コップの水に氷を入れてください。氷は下へ行きません。水の上にあります。",zh:"冰比水輕。請把冰塊放進杯子的水裡。冰塊不會沉下去，會浮在水面上。"},{ja:"雨が降ったあと、道に水があります。でも、晴れた日には、その水は少しずつなくなります。水は空へ行って、雲になります。",zh:"下過雨之後，路上會有水。但是到了晴天，那些水會一點一點地不見。水跑到天空，變成了雲。"},{ja:"雲の中の水は、また雨や雪になって、降ります。水は、氷にも雲にも雨にもなります。おもしろいですね。",zh:"雲裡的水又會變成雨或雪落下來。水可以變成冰，也可以變成雲和雨。很有趣吧。"}],vocab:[{word:"池",reading:"いけ",meaning:"池塘"},{word:"氷",reading:"こおり",meaning:"冰"},{word:"軽い",reading:"かるい",meaning:"輕的"},{word:"道",reading:"みち",meaning:"路、道路"},{word:"晴れる",reading:"はれる",meaning:"放晴"},{word:"空",reading:"そら",meaning:"天空"},{word:"雲",reading:"くも",meaning:"雲"},{word:"降る",reading:"ふる",meaning:"（雨、雪）下、降"}],questions:[{question:"コップの水に氷を入れました。氷はどこにありますか。",questionZh:"把冰塊放進杯子的水裡。冰塊會在哪裡？",options:["水の上にあります","コップの下にあります","コップの外へ出ます","すぐ雲になります"]},{question:"文によると、晴れた日に、道の水はどうなりますか。",questionZh:"根據文章，晴天時路上的水會怎麼樣？",options:["空へ行って、雲になります","池に入って、氷になります","道の上で、雪になります","大きくなって、川になります"]}]},{id:"n5-r19",title:"父のかぎ",titleZh:"爸爸的鑰匙",topic:"推理",paragraphs:[{ja:"月曜日の朝、父が「家のかぎがありません」と言いました。父はかばんの中と机の上を見ました。でも、かぎはありませんでした。",zh:"星期一早上，爸爸說：「家裡的鑰匙不見了。」爸爸看了包包裡面和桌子上面。但是都沒有鑰匙。"},{ja:"私はきのうの夜のことを考えました。父はコンビニで牛乳を買って、帰ってきました。左手にかばん、右手に牛乳とかぎを持っていました。",zh:"我想了想昨天晚上的事。爸爸在便利商店買了牛奶後回家。他左手拿著包包，右手拿著牛奶和鑰匙。"},{ja:"父は家に入って、すぐ台所へ行きました。そして、冷蔵庫に牛乳を入れました。",zh:"爸爸進了家門，馬上就去了廚房。然後把牛奶放進了冰箱。"},{ja:"私は冷蔵庫を開けました。牛乳のとなりに、かぎがありました。父は「ありがとう、小さい探偵さん」と言って、笑いました。",zh:"我打開冰箱。牛奶旁邊就是鑰匙。爸爸說：「謝謝你，小偵探。」然後笑了。"}],vocab:[{word:"かぎ",reading:"かぎ",meaning:"鑰匙"},{word:"机",reading:"つくえ",meaning:"桌子、書桌"},{word:"牛乳",reading:"ぎゅうにゅう",meaning:"牛奶"},{word:"左手",reading:"ひだりて",meaning:"左手"},{word:"右手",reading:"みぎて",meaning:"右手"},{word:"台所",reading:"だいどころ",meaning:"廚房"},{word:"冷蔵庫",reading:"れいぞうこ",meaning:"冰箱"},{word:"笑う",reading:"わらう",meaning:"笑"}],questions:[{question:"きのうの夜、父は右手に何を持っていましたか。",questionZh:"昨天晚上，爸爸右手拿著什麼？",options:["牛乳とかぎ","かばんとかぎ","牛乳とかばん","傘とかぎ"]},{question:"かぎはどこにありましたか。",questionZh:"鑰匙在哪裡？",options:["冷蔵庫の中","かばんの中","机の上","テレビの前"]}]},{id:"n5-r20",title:"なくなった魚",titleZh:"不見的魚",topic:"推理",paragraphs:[{ja:"土曜日の夕方、母が魚を三匹焼きました。母は魚をテーブルの上に置いて、二階へ行きました。",zh:"星期六傍晚，媽媽烤了三條魚。媽媽把魚放在桌子上，然後去了二樓。"},{ja:"十分ぐらいあとで、母と私は台所へ行きました。テーブルの上には、魚が二匹だけありました。それに、白くて短い毛が少しありました。",zh:"大約十分鐘後，媽媽和我去了廚房。桌上只剩下兩條魚。而且，還有一些白色的短毛。"},{ja:"そのとき、家には弟と犬のポチと猫のシロがいました。弟は「ぼくはポチと庭で遊んでいました」と言いました。ポチは茶色い犬です。シロは白い猫です。",zh:"那時候，家裡有弟弟、狗狗波奇和貓咪小白。弟弟說：「我和波奇在院子裡玩。」波奇是一隻咖啡色的狗。小白是一隻白色的貓。"},{ja:"私は「魚を食べたのはシロですね」と言いました。いすの下で、シロが「ニャー」と鳴きました。",zh:"我說：「吃掉魚的是小白吧。」小白在椅子下面「喵」地叫了一聲。"}],vocab:[{word:"魚",reading:"さかな",meaning:"魚"},{word:"焼く",reading:"やく",meaning:"烤、煎"},{word:"置く",reading:"おく",meaning:"放、放置"},{word:"毛",reading:"け",meaning:"毛"},{word:"庭",reading:"にわ",meaning:"院子"},{word:"茶色い",reading:"ちゃいろい",meaning:"咖啡色的"},{word:"猫",reading:"ねこ",meaning:"貓"},{word:"鳴く",reading:"なく",meaning:"（鳥、動物）叫、鳴叫"}],questions:[{question:"母と私が台所へ行ったとき、テーブルの上に何がありましたか。",questionZh:"媽媽和我去廚房的時候，桌上有什麼？",options:["魚二匹と白い毛","魚三匹と白い毛","魚二匹と茶色い毛","魚一匹と黒い毛"]},{question:"弟はそのとき、何をしていましたか。",questionZh:"弟弟那時候在做什麼？",options:["庭でポチと遊んでいました","台所で魚を食べていました","二階で母と話していました","部屋で勉強していました"]},{question:"魚を食べたのはだれですか。",questionZh:"吃掉魚的是誰？",options:["猫のシロ","犬のポチ","弟","母"]}]}]},1232,[]);
